import {calculateQuote, calculateActual} from './engine.mjs';
const $=id=>document.getElementById(id);
const edition=document.body.dataset.edition;
const preview=edition!=='customer';
const storageKey='cleanquote-v1-'+(preview?'preview':'customer');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numeric=['hours','hourlyPay','supplies','travel','overhead','margin','feeRate','fixedFee','discount','taxRate','validDays'];
const quoteText=['id','customer','reference','address','service','date','scope','notes','status'];
const businessText=['name','email','phone','website','color','reviewUrl','terms','logo'];
const defaults={name:preview?'Moss & Mop · Sample business':'Your cleaning business',email:preview?'hello@example.com':'',phone:'',website:'',color:'#173e32',reviewUrl:'',terms:'Estimate is based on the scope described. Please confirm access, condition, and any additional tasks before the job. Final scheduling is agreed separately.',logo:''};
function newDraft(sample=false){return {id:crypto.randomUUID(),customer:sample?'Jamie · Sample client':'',reference:'CQ-'+String(Date.now()).slice(-6),address:sample?'Sample property · 3 bedrooms, 2 bathrooms':'',service:'Deep cleaning',date:new Date().toLocaleDateString('en-CA'),scope:sample?'Kitchen: counters, sink, appliance exteriors\nBathrooms: sinks, toilets, tubs, and showers\nAll rooms: dust reachable surfaces, vacuum, and mop\nExcludes: inside oven, inside windows, and high-access work.':'',notes:state?.business?.terms??defaults.terms,status:'draft',validDays:14,hours:sample?4:0,hourlyPay:sample?25:0,supplies:sample?8:0,travel:sample?10:0,overhead:sample?12:0,margin:sample?25:20,discount:0,taxRate:0,feeRate:0,fixedFee:0,actualHours:'',actualSupplies:'',actualTravel:'',actualOverhead:''};}
let state={schemaVersion:1,business:{...defaults},records:[],draft:null};
state.draft=newDraft(preview);
let pendingRestore=null,toastTimer,lastResult=null;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function isLogo(value){return value===''||(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value)&&value.length<1500000);}
function cleanBusiness(raw){if(!raw||typeof raw!=='object')throw Error('Missing business profile.');const b={};for(const key of businessText){if(typeof raw[key]!=='string'||raw[key].length>(key==='logo'?1500000:3000))throw Error('Invalid business profile.');b[key]=raw[key];}if(!/^#[0-9a-fA-F]{6}$/.test(b.color)||!isLogo(b.logo))throw Error('Invalid logo or brand color.');return b;}
function cleanQuote(raw){if(!raw||typeof raw!=='object')throw Error('Invalid quote.');const q={};for(const key of quoteText){if(typeof raw[key]!=='string'||raw[key].length>3000)throw Error('Invalid quote text.');q[key]=raw[key];}if(!/^[\w-]{1,100}$/.test(q.id)||!/^\d{4}-\d{2}-\d{2}$/.test(q.date)||Number.isNaN(Date.parse(q.date))||!['draft','sent','accepted','completed'].includes(q.status))throw Error('Invalid quote identifier, date, or status.');for(const key of numeric){if(typeof raw[key]!=='number'||!Number.isFinite(raw[key])||raw[key]<0)throw Error('Invalid quote numbers.');q[key]=raw[key];}if(q.validDays<1||q.validDays>365)throw Error('Invalid validity period.');calculateQuote(q);for(const key of ['actualHours','actualSupplies','actualTravel','actualOverhead']){const value=raw[key]??'';if(value!==''&&(typeof value!=='number'||!Number.isFinite(value)||value<0||value>100000))throw Error('Invalid actual job costs.');q[key]=value;}if(q.actualHours!=='')calculateActual(q,{hours:q.actualHours,supplies:q.actualSupplies===''?q.supplies:q.actualSupplies,travel:q.actualTravel===''?q.travel:q.actualTravel,overhead:q.actualOverhead===''?q.overhead:q.actualOverhead});if(raw.business)q.business=cleanBusiness(raw.business);return q;}
function cleanState(raw){if(raw?.schemaVersion!==1||!Array.isArray(raw.records)||raw.records.length>10000)throw Error('This is not a supported CleanQuote backup.');const records=raw.records.map(cleanQuote);if(new Set(records.map(r=>r.id)).size!==records.length)throw Error('Backup contains duplicate quote IDs.');return {schemaVersion:1,business:cleanBusiness(raw.business),draft:cleanQuote(raw.draft),records};}
try{const stored=localStorage.getItem(storageKey);if(stored)state=cleanState(JSON.parse(stored));}catch{toast('Saved data could not be read. Your previous storage has not been overwritten. Restore a backup or start a fresh quote.');}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));$('save-indicator').textContent='Draft saved on this device';}catch{$('save-indicator').textContent='Storage unavailable — export a backup';toast('This browser could not save your work. Export a backup before closing.');}}
function loadForm(){for(const el of $('quote-form').elements)if(el.name&&Object.hasOwn(state.draft,el.name))el.value=state.draft[el.name];render();}
function readForm(){const q={...state.draft};for(const el of $('quote-form').elements){if(!el.name)continue;if(numeric.includes(el.name))q[el.name]=el.value===''?NaN:Number(el.value);else if(el.name.startsWith('actual'))q[el.name]=el.value===''?'':Number(el.value);else q[el.name]=el.value;}return q;}
function view(name){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!=='view-'+name);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const headings={builder:['YOUR NEXT CLEAN','Let’s make it a clear quote.'],jobs:['A LITTLE MORE ORGANIZED','Every quote. In one place.'],business:['YOUR NAME ON THE WORK','Make it feel like your business.'],backup:['KEEP A COPY','Your work deserves a backup.']};$('view-eyebrow').textContent=headings[name][0];$('view-heading').textContent=headings[name][1];if(name==='jobs')renderJobs();if(name==='business')loadBusiness();}
function currentBusiness(){return state.draft.business??state.business;}
function documentHTML(q,r,b){const expiry=new Date(q.date+'T12:00:00');expiry.setDate(expiry.getDate()+q.validDays);return `<div class="quote-document" style="--document-color:${esc(b.color)}"><div class="document-head"><div>${b.logo?`<img class="document-logo" src="${b.logo}" alt="Business logo">`:''}<div class="document-business">${esc(b.name)}</div><div class="document-contact">${esc([b.email,b.phone,b.website].filter(Boolean).join('\n'))}</div></div><div class="document-label"><b>ESTIMATE</b>${esc(q.reference)}<br>${esc(q.date)}<br>Valid for ${q.validDays} days</div></div><div class="document-recipient">PREPARED FOR<b>${esc(q.customer||'Customer name')}</b>${esc(q.address)}</div><h2 class="document-title">${esc(q.service)}</h2><div class="document-scope">${esc(q.scope||'Add the tasks and exclusions included in this quote.')}</div><div class="document-amounts"><div><span>Cleaning service</span><span>${money(r.basePrice)}</span></div>${r.discountAmount?`<div><span>Discount (${q.discount}%)</span><span>−${money(r.discountAmount)}</span></div>`:''}${r.tax?`<div><span>Tax (${q.taxRate}%)</span><span>${money(r.tax)}</span></div>`:''}<div class="grand-total"><span>Your estimate</span><span>${money(r.total)}</span></div></div><div class="document-terms">${esc(q.notes)}</div><div class="document-footer">Quote valid through ${esc(expiry.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}))}. Please confirm scope and scheduling directly with ${esc(b.name)}.</div>${preview?'<p class="demo-watermark">CLEANQUOTE DEMO · NOT A LIVE CUSTOMER ESTIMATE</p>':''}</div>`;}
function makeMessage(q,r,b){const first=q.customer.trim().split(/\s/)[0]||'there';const total=r?money(r.total):'the quoted amount';if($('message-type').value==='followup')return `Hi ${first}, just checking whether you had any questions about the ${q.service.toLowerCase()} estimate (${q.reference}) for ${total}. Happy to clarify the scope or discuss scheduling. Thank you! — ${b.name}`;if($('message-type').value==='review')return `Hi ${first}, thank you for choosing ${b.name}. If you’d like to share an honest review of your experience, ${b.reviewUrl?'you can leave one here: '+b.reviewUrl:'please ask me for our review page link'}. Your feedback is appreciated.`;return `Hi ${first}, here’s your ${q.service.toLowerCase()} estimate from ${b.name}: ${total}. I’ve included the scope and terms in the attached estimate. Please take a look and let me know if you have any questions or would like to discuss a time. Thank you!`;} 
function render(){const q=state.draft;$('saved-count').textContent=String(state.records.length);try{const r=calculateQuote(q);lastResult=r;$('calculation-error').hidden=true;for(const [id,value] of [['total',r.total],['labor',r.labor],['cost',r.costs-r.labor],['fee',r.processingFee],['tax',r.tax],['profit',r.profit]])$(id+'-value').textContent=money(value);$('margin-note').textContent=`${r.marginActual.toFixed(1)}% estimated margin after discounts and entered fees. Based on your inputs.`;$('margin-note').style.color=r.profit<0?'#ffc5a3':'';for(const [id,value]of [['labor',r.labor],['other',r.costs-r.labor],['fee',r.processingFee],['profit',Math.max(0,r.profit)],['tax',r.tax]])$(id+'-bar').style.width=(r.total>0?Math.max(0,value/r.total*100):0)+'%';$('quote-preview').innerHTML=documentHTML(q,r,currentBusiness());$('message-text').value=makeMessage(q,r,currentBusiness());if(q.actualHours!==''){const a=calculateActual(q,{hours:q.actualHours,supplies:q.actualSupplies===''?q.supplies:q.actualSupplies,travel:q.actualTravel===''?q.travel:q.actualTravel,overhead:q.actualOverhead===''?q.overhead:q.actualOverhead});$('actual-result').innerHTML=`Labor compensation: <b>${money(a.ownerCompensation)}</b><br>Actual business profit: <b>${money(a.profit)}</b><br>Difference from plan: <b>${a.profitDifference>=0?'+':''}${money(a.profitDifference)}</b>`;}else $('actual-result').textContent='Enter actual hours to compare this job.';}catch(error){lastResult=null;$('calculation-error').textContent=error.message;$('calculation-error').hidden=false;$('quote-preview').textContent='Review the inputs to create a valid customer estimate.';for(const id of ['total','labor','cost','fee','tax','profit'])$(id+'-value').textContent='—';$('message-text').value='Review the quote inputs first.';$('actual-result').textContent='Review the quote and actual-cost inputs.';}}
function saveQuote(){const form=$('quote-form');if(!form.reportValidity())return;try{const q=cleanQuote({...readForm(),business:{...currentBusiness()}});if(!q.customer.trim()||!q.reference.trim())throw Error('Add a customer name and quote reference.');const index=state.records.findIndex(r=>r.id===q.id);if(index===-1)state.records.unshift(q);else state.records[index]=q;state.draft={...q};persist();render();toast('Quote saved on this device. Export a backup to keep a separate copy.');}catch(error){toast(error.message);}}
$('quote-form').addEventListener('input',()=>{state.draft=readForm();render();if(lastResult)persist();});$('quote-form').addEventListener('submit',event=>{event.preventDefault();saveQuote();});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
$('new-quote').addEventListener('click',()=>{if(!lastResult){toast('Correct the current inputs before starting another quote.');return;}state.draft=newDraft();persist();loadForm();view('builder');$('quote-form').elements.customer.focus();});
$('duplicate').addEventListener('click',()=>{if(!lastResult)return toast('Correct the inputs first.');state.draft={...state.draft,id:crypto.randomUUID(),reference:'CQ-'+String(Date.now()).slice(-6),status:'draft'};persist();loadForm();toast('Created a separate copy. Save it to add it to your jobs.');});
$('print-quote').addEventListener('click',()=>{if(!lastResult)return toast('Correct the inputs before printing.');if(!$('quote-form').reportValidity())return;$('print-area').innerHTML=documentHTML(state.draft,lastResult,currentBusiness());window.print();});
$('message-type').addEventListener('change',()=>render());$('copy-message').addEventListener('click',async()=>{if(!lastResult)return;try{await navigator.clipboard.writeText($('message-text').value);toast('Message copied. Paste it into your text or email app.');}catch{$('message-text').focus();$('message-text').select();toast('Select and copy the highlighted message using your keyboard.');}});
function renderJobs(){const query=$('job-search').value.toLowerCase().trim();const jobs=state.records.filter(q=>(q.customer+' '+q.reference).toLowerCase().includes(query));$('jobs-list').innerHTML=jobs.length?jobs.map(q=>{const r=calculateQuote(q);return `<article class="job-card"><div class="job-top"><span>${esc(q.reference)} · ${esc(q.date)}</span><span class="status-pill">${esc(q.status)}</span></div><h2>${esc(q.customer)}</h2><p>${esc(q.service)}<br>${esc(q.address)}</p><strong class="job-price">${money(r.total)}</strong><div class="job-bottom"><button class="button secondary" data-open="${q.id}">Open quote ↗</button><button class="text-button" data-archive="${q.id}">Delete quote</button></div></article>`;}).join(''):`<div class="empty-state"><h2>${query?'No matching quotes.':'A clean slate.'}</h2><p>${query?'Try another customer name or reference.':'Save your first quote and it will appear here. Your records stay on this device.'}</p></div>`;}
$('job-search').addEventListener('input',renderJobs);let deletePending=null;$('jobs-list').addEventListener('click',event=>{const open=event.target.closest('[data-open]');if(open){state.draft=structuredClone(state.records.find(q=>q.id===open.dataset.open));persist();loadForm();view('builder');window.scrollTo({top:0,behavior:'smooth'});}const remove=event.target.closest('[data-archive]');if(remove){if(deletePending!==remove.dataset.archive){deletePending=remove.dataset.archive;remove.textContent='Click again to delete';setTimeout(()=>{deletePending=null;if(remove.isConnected)remove.textContent='Delete quote';},5000);return;}state.records=state.records.filter(q=>q.id!==remove.dataset.archive);deletePending=null;persist();renderJobs();$('saved-count').textContent=state.records.length;toast('Quote removed from saved jobs.');}});
function loadBusiness(){for(const el of $('business-form').elements)if(el.name)el.value=state.business[el.name]??'';}
$('business-form').addEventListener('submit',event=>{event.preventDefault();const form=$('business-form');if(!form.reportValidity())return;const b={...state.business};for(const el of form.elements)if(el.name)b[el.name]=el.value;try{state.business=cleanBusiness(b);delete state.draft.business;persist();render();toast('Business profile saved. The current draft now uses this profile.');}catch(error){toast(error.message);}});
$('logo-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1024*1024){event.target.value='';return toast('Choose a PNG, JPG, or WebP image up to 1 MB.');}const reader=new FileReader();reader.onload=()=>{if(!isLogo(reader.result))return toast('This logo format could not be read.');state.business.logo=reader.result;delete state.draft.business;persist();render();toast('Logo saved to this device.');};reader.readAsDataURL(file);});$('remove-logo').addEventListener('click',()=>{state.business.logo='';delete state.draft.business;persist();render();toast('Logo removed from the current profile.');});
function download(name,type,content){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-backup').addEventListener('click',()=>{try{const backup=cleanState(state);download('cleanquote-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json',JSON.stringify(backup,null,2));toast('Backup exported. Keep it somewhere private and separate from this browser.');}catch{toast('Correct the current inputs before exporting a backup.');}});
$('import-backup').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>15000000)throw Error('This backup is too large.');pendingRestore=cleanState(JSON.parse(await file.text()));$('restore-summary').textContent=`The backup contains ${pendingRestore.records.length} saved quote(s) for ${pendingRestore.business.name}.`;$('restore-dialog').showModal();}catch(error){pendingRestore=null;toast('Backup not imported. '+error.message);}});
$('cancel-restore').addEventListener('click',()=>{pendingRestore=null;$('restore-dialog').close();});$('confirm-restore').addEventListener('click',()=>{if(!pendingRestore)return;state=pendingRestore;pendingRestore=null;persist();loadForm();$('restore-dialog').close();toast('Backup restored to this device.');});
function csvCell(v){let value=String(v??'');if(/^[=+\-@\t\r]/.test(value))value="'"+value;return '"'+value.replaceAll('"','""')+'"';}
$('export-csv').addEventListener('click',()=>{const rows=[['Reference','Customer','Date','Service','Status','Total USD','Labor compensation USD','Estimated profit USD'],...state.records.map(q=>{const r=calculateQuote(q);return[q.reference,q.customer,q.date,q.service,q.status,r.total,r.labor,r.profit];})];download('cleanquote-jobs.csv','text/csv;charset=utf-8',rows.map(row=>row.map(csvCell).join(',')).join('\r\n'));toast('Saved jobs exported as CSV. The JSON backup is used to restore the app.');});
if(!preview){$('edition-banner').hidden=true;$('edition-help').textContent='You are using the downloadable customer edition. Keep a copy of the app file and regularly export your records.';document.querySelector('.sidebar-bottom>a').hidden=true;document.querySelector('.sidebar>.brand').href='#';}
loadForm();loadBusiness();
